+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+::deep .close-btn:hover {
+    background: #4f545c;
+    color: #fff;
+}
+
+::deep .thread-root-message {
+    padding: 12px 16px;
+    background: #36393f;
+    border-bottom: 1px solid #202225;
+}
+
+::deep .thread-root-message .author {
+    font-size: 0.85rem;
+}
+
+::deep .thread-root-message p {
+    margin: 6px 0 0;
+    font-size: 0.85rem;
+    color: #b9bbbe;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+    display: flex;
+    flex-direction: column;
+    gap: 8px;
+}
+
+::deep .thread-reply {
+    padding: 8px;
+    border-radius: 4px;
+}
+
+::deep .thread-reply:hover {
+    background: #36393f;
+}
+
+/* Layout adjustment when thread is closed */
+.chat-layout:not(.thread-open) ::deep .message-area {
+    width: 80%;
+}
+
+.chat-layout.thread-open ::deep .message-area {
+    width: 55%;
+}
+

